const registros = $input.all();
const consulta = String(
  $('Edit Fields').first().json.consulta_usuario || ""
);

// Normalizar textos
function normalizar(texto) {
  return String(texto || "")
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/[^a-z0-9\s]/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}

// Palabras generales que no ayudan a identificar la consulta
const ignoradas = new Set([
  "que", "como", "para", "una", "uno", "unos", "unas",
  "con", "los", "las", "del", "por", "desde", "hasta",
  "necesito", "quiero", "saber", "puedo", "tengo",
  "hacer", "cual", "cuales", "donde", "cuando",
  "cuanto", "cuantos", "cuanta", "cuantas",
  "este", "esta", "estos", "estas", "sobre",
  "banco", "bancaria", "bancario", "entidad",
  "ofrece", "hoy", "exacta", "exacto",
  "dinero", "pesos"
]);

function palabras(texto) {
  return [...new Set(
    normalizar(texto)
      .split(" ")
      .filter(p => p.length > 2 && !ignoradas.has(p))
  )];
}

// Unificar variantes habituales de palabras
function raiz(palabra) {
  const equivalencias = {
    prestamos: "prestamo",
    prestamos_personales: "prestamo",
    personales: "personal",
    cuentas: "cuenta",
    tarjetas: "tarjeta",
    intereses: "interes",
    tasas: "tasa",
    requisitos: "requisito",
    documentos: "documentacion",
    documentacion: "documentacion",
    claves: "clave",
    contrasenas: "contrasena",
    movimientos: "movimiento",
    transferencias: "transferencia",
    comisiones: "comision",
    costos: "costo",
    saldos: "saldo"
  };
  return equivalencias[palabra] || palabra;
}

function tokens(texto) {
  return palabras(texto).map(raiz);
}

// Identificar temas bancarios principales
const temas = {
  prestamo: ["prestamo", "credito", "financiacion"],
  cuenta: ["cuenta", "caja", "ahorro"],
  tarjeta: ["tarjeta", "debito", "credito"],
  transferencia: ["transferencia", "cbu", "alias"],
  seguridad: ["pin", "clave", "contrasena", "token", "fraude"],
  plazo_fijo: ["plazo fijo"],
  seguro: ["seguro", "poliza"]
};

function detectarTemas(texto) {
  const limpio = normalizar(texto);
  const encontrados = [];

  for (const [tema, terminos] of Object.entries(temas)) {
    if (terminos.some(t =>
      limpio.split(" ").includes(t) ||
      (t.includes(" ") && limpio.includes(t))
    )) {
      encontrados.push(tema);
    }
  }

  return encontrados;
}

const consultaTokens = tokens(consulta);
const temasConsulta = detectarTemas(consulta);

// Buscar coincidencias
const candidatos = registros.map(item => {
  const fila = item.json;

  const pregunta = tokens(fila.PREGUNTA);
  const producto = tokens(fila.PRODUCTO);
  const categoria = tokens(fila.CATEGORIA || fila.CATEGORÍA);

  const temasRegistro = detectarTemas(
    `${fila.CATEGORIA || fila.CATEGORÍA || ""} ` +
    `${fila.PRODUCTO || ""} ${fila.PREGUNTA || ""}`
  );

  const coincidenciasPregunta = consultaTokens.filter(
    p => pregunta.includes(p)
  ).length;

  const coincidenciasProducto = consultaTokens.filter(
    p => producto.includes(p)
  ).length;

  const coincidenciasCategoria = consultaTokens.filter(
    p => categoria.includes(p)
  ).length;

  const temasComunes = temasConsulta.filter(
    t => temasRegistro.includes(t)
  ).length;

  const conflictoTema =
    temasConsulta.length > 0 &&
    temasRegistro.length > 0 &&
    temasComunes === 0;

  let puntaje =
    coincidenciasPregunta * 3 +
    coincidenciasProducto * 2 +
    coincidenciasCategoria +
    temasComunes * 4;

  if (normalizar(fila.PREGUNTA) === normalizar(consulta)) {
    puntaje += 20;
  }

  if (conflictoTema) {
    puntaje -= 8;
  }

  return {
    ...fila,
    puntaje
  };
})
.filter(fila => fila.puntaje >= 4)
.sort((a, b) => b.puntaje - a.puntaje);

const coincidencias = candidatos.slice(0, 5);


 // Clasificar el tipo de consulta del usuario
function clasificarConsulta(texto) {
  const consultaNormalizada = normalizar(texto);

  const solicitaDatoPersonal =
    /\b(mi saldo|mis movimientos|mi cuenta|cuanto dinero tengo)\b/.test(
      consultaNormalizada
    );

  const solicitaDatoActualizado =
    /\b(hoy|actual|actualizada|actualizado|vigente|vigentes)\b/.test(
      consultaNormalizada
    ) &&
    /\b(tasa|tasas|interes|cotizacion|precio|rendimiento|tna|tea)\b/.test(
      consultaNormalizada
    );

  if (solicitaDatoPersonal) {
    return "INFORMACION_PERSONAL";
  }

  if (solicitaDatoActualizado) {
    return "INFORMACION_ACTUALIZADA";
  }

  return "INFORMACION_GENERAL";
}

const tipoConsulta = clasificarConsulta(consulta);


// Devolver un único artículo al Agente de IA
return [{
  json: {
    consulta_usuario: consulta,
    tipo_consulta: tipoConsulta,
    registros_totales: registros.length,
    coincidencias_encontradas: coincidencias.length,
    resultados: coincidencias
  }
}];
